/*
 * A169311  Number of reduced words of length n in Coxeter group on 10
 *          generators S_i with relations (S_i)^2 = (S_i S_j)^30 = I.
 * https://oeis.org/A169311
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn
 * Formula:   A169311 is generated by the recurrence * * a(0) = 1 * for n ≥ 1
 *            * let S(n) = Σ_{k=max(0,n-29)}^{n-1} a(k) * let p(n) = 1 if n ==
 *            0 or n == 30 * 2 if 1 ≤ n ≤ 29 * 0 otherwise * a(n) = 8·S(n) –
 *            36·a(n‑30) + p(n) * * The coefficients come from the generating
 *            function * (t^30 + 2t^29 + … + 2t + 1) /...
 * Range:     u8 n <= 2, u16 n <= 4, u32 n <= 10, u64 n <= 18, u128 n <= 18,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>

seq_t a(idx_t n)
{
    /* static cache: a[0] .. a[cache_size-1] are valid */
    static seq_t *cache = NULL;
    static size_t cache_size = 0;  /* number of stored terms */
    static size_t cache_cap   = 0;  /* current allocation capacity */

    /* Grow cache if needed */
    if (n + 1 > cache_cap) {
        size_t new_cap = cache_cap ? (cache_cap << 1) : 64;
        while (new_cap < (size_t)n + 1) new_cap <<= 1;
        seq_t *tmp = (seq_t *)realloc(cache, new_cap * sizeof(seq_t));
        cache = tmp;
        cache_cap = new_cap;
    }

    /* Initialise first term */
    if (cache_size == 0) {
        cache[0] = (seq_t)1;
        cache_size = 1;
    }

    /* Compute terms up to n */
    for (size_t i = cache_size; i <= (size_t)n; ++i) {
        /* Sum of the last up to 29 previous values */
        seq_t sum = (seq_t)0;
        size_t start = (i >= 29) ? (i - 29) : 0;
        for (size_t j = start; j < i; ++j) sum += cache[j];

        /* a(i) = 8*sum – 36*a(i-30) + p(i) */
        seq_t res = sum * (seq_t)8;
        if (i >= 30) {
            res -= (seq_t)36 * cache[i - 30];
        }
        if (i == 0 || i == 30) {
            res += (seq_t)1;
        } else if (i <= 29) {
            res += (seq_t)2;
        }
        cache[i] = res;
    }
    cache_size = (size_t)n + 1;
    return cache[(size_t)n];
}
